CREATE TABLE grant_audit (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, actor_id bigint REFERENCES users(id), subject_user_id bigint REFERENCES users(id), action text NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION demand_count(s text) RETURNS bigint LANGUAGE sql STABLE AS $$ SELECT count(*) FROM demands WHERE status=s $$;
CREATE FUNCTION requester_demand_count(u bigint) RETURNS bigint LANGUAGE sql STABLE AS $$ SELECT count(*) FROM demands WHERE requester_id=u $$;
CREATE FUNCTION published_page_count() RETURNS bigint LANGUAGE sql STABLE AS $$ SELECT count(*) FROM pages WHERE published_version_id IS NOT NULL $$;
CREATE FUNCTION transition_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.status<>OLD.status AND NOT ((OLD.status='Pendente' AND NEW.status IN ('Aceita para atendimento','Recusada','Cancelada')) OR (OLD.status='Aceita para atendimento' AND NEW.status IN ('Em atendimento','Cancelada')) OR (OLD.status='Em atendimento' AND NEW.status IN ('Concluída','Cancelada'))) THEN RAISE EXCEPTION 'transição inválida'; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER transition_guard BEFORE UPDATE ON demands FOR EACH ROW EXECUTE FUNCTION transition_guard();
CREATE FUNCTION event_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'evento imutável'; END $$;
CREATE TRIGGER event_immutable BEFORE UPDATE OR DELETE ON demand_events FOR EACH ROW EXECUTE FUNCTION event_immutable();
CREATE FUNCTION page_publish_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.published_version_id IS DISTINCT FROM OLD.published_version_id THEN INSERT INTO page_events(page_id,version_id,actor_id,action) VALUES(NEW.id,NEW.published_version_id,current_setting('ites.actor_id')::bigint,CASE WHEN NEW.published_version_id IS NULL THEN 'UNPUBLISH' ELSE 'PUBLISH' END); END IF; RETURN NEW; END $$;
CREATE TRIGGER page_publish_audit AFTER UPDATE OF published_version_id ON pages FOR EACH ROW EXECUTE FUNCTION page_publish_audit();
CREATE PROCEDURE transition_demand(i bigint,a bigint,s text,r text,c text DEFAULT NULL) LANGUAGE plpgsql AS $$ DECLARE old_s text; BEGIN IF nullif(btrim(r),'') IS NULL THEN RAISE EXCEPTION 'justificativa obrigatória'; END IF; SELECT status INTO old_s FROM demands WHERE id=i FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'não encontrado'; END IF; UPDATE demands SET status=s,completion_note=COALESCE(c,completion_note) WHERE id=i; INSERT INTO demand_events(demand_id,actor_id,old_status,new_status,justification) VALUES(i,a,old_s,s,r); END $$;
CREATE PROCEDURE publish_page(p bigint,v bigint,a bigint) LANGUAGE plpgsql AS $$ BEGIN PERFORM set_config('ites.actor_id',a::text,true); IF NOT EXISTS(SELECT 1 FROM page_versions WHERE id=v AND page_id=p) THEN RAISE EXCEPTION 'versão inválida'; END IF; UPDATE pages SET published_version_id=v WHERE id=p; END $$;
CREATE PROCEDURE assign_role(u bigint,r bigint,a bigint) LANGUAGE plpgsql AS $$ BEGIN INSERT INTO user_roles VALUES(u,r) ON CONFLICT DO NOTHING; INSERT INTO grant_audit(actor_id,subject_user_id,action) VALUES(a,u,'ASSIGN_ROLE:'||r); END $$;
